.qly-form-wrap{max-width:640px;margin:0 auto;background:#FFFFFF;border:1px solid rgba(10, 77, 82, 0.16);border-radius:14px;box-shadow:0 2px 14px rgba(10, 77, 82, 0.08);padding:28px 24px;font-family:Inter,-apple-system,sans-serif;}
.qly-form-wrap .qly-row{display:flex;gap:14px;flex-wrap:wrap;margin-bottom:14px;}
.qly-form-wrap .qly-field{flex:1 1 240px;display:flex;flex-direction:column;}
.qly-form-wrap label{font-size:14px;font-weight:600;color:#2B2D42;margin-bottom:6px;}
.qly-form-wrap input,.qly-form-wrap select,.qly-form-wrap textarea{font-family:inherit;font-size:15px;padding:12px 14px;border:1px solid rgba(10, 77, 82, 0.25);border-radius:8px;color:#2B2D42;background:#FFFFFF;width:100%;box-sizing:border-box;}
.qly-form-wrap input:focus,.qly-form-wrap select:focus,.qly-form-wrap textarea:focus{outline:2px solid #005F73;outline-offset:1px;}
.qly-form-wrap textarea{min-height:100px;resize:vertical;}
.qly-hp{position:absolute;left:-9999px;top:auto;width:1px;height:1px;overflow:hidden;}
.qly-form-submit{display:inline-block;background:#EAB308;color:#FFFFFF;font-weight:700;font-size:16px;padding:14px 30px;border-radius:999px;border:none;cursor:pointer;min-height:44px;width:100%;}
.qly-form-submit:hover{background:#EAB308;}
.qly-form-submit:disabled{opacity:0.6;cursor:not-allowed;}
.qly-form-msg{margin-top:14px;font-size:14px;font-weight:600;padding:12px 14px;border-radius:8px;display:none;}
.qly-form-msg.qly-ok{display:block;background:rgba(10, 77, 82, 0.12);color:#005F73;}
.qly-form-msg.qly-err{display:block;background:rgba(234,88,12,0.10);color:#9a3412;}
</style>
<form class="qly-form-wrap" id="qly-free-trial-form" novalidate>
  <div class="qly-row">
    <div class="qly-field"><label for="qly-name">Full Name *</label><input type="text" id="qly-name" name="name" required maxlength="150"></div>
    <div class="qly-field"><label for="qly-email">Email *</label><input type="email" id="qly-email" name="email" required></div>
  </div>
  <div class="qly-row">
    <div class="qly-field"><label for="qly-whatsapp">WhatsApp / Phone Number *</label><input type="tel" id="qly-whatsapp" name="whatsapp" required maxlength="40" placeholder="+1 555 000 0000"></div>
    <div class="qly-field"><label for="qly-country">Country</label>
      <select id="qly-country" name="country">
        <option value="">Select your country</option>
        <option>United Kingdom</option><option>United States</option><option>Canada</option><option>Australia</option><option>United Arab Emirates</option><option>Qatar</option><option>Saudi Arabia</option><option>Other</option>
      </select>
    </div>
  </div>
  <div class="qly-row">
    <div class="qly-field"><label for="qly-course">Course of Interest</label>
      <select id="qly-course" name="course">
        <option value="">Not sure yet</option>
        <option>Noorani Qaida</option><option>Quran Reading with Tajweed</option><option>Advanced Tajweed</option><option>Quran Memorization (Hifz)</option><option>Tafseer</option><option>Learn Quranic Arabic</option>
      </select>
    </div>
    <div class="qly-field"><label for="qly-plan">Preferred Class Frequency</label>
      <select id="qly-plan" name="plan">
        <option value="">Not sure yet</option>
        <option>Once a week</option><option>Twice a week</option><option>Three or more times a week</option><option>Daily</option>
      </select>
    </div>
  </div>
  <div class="qly-row">
    <div class="qly-field"><label for="qly-timing">Preferred Timing</label>
      <select id="qly-timing" name="timing">
        <option value="">Not sure yet</option>
        <option>Mornings</option><option>Afternoons</option><option>Evenings</option><option>Weekends</option>
      </select>
    </div>
  </div>
  <div class="qly-row">
    <div class="qly-field"><label for="qly-message">Additional Message or Requirements</label><textarea id="qly-message" name="message" maxlength="1000" placeholder="Tell us anything that will help us prepare, e.g. your child's age, current level, or time zone."></textarea></div>
  </div>
  <div class="qly-hp"><label for="qly-website">Leave this field empty</label><input type="text" id="qly-website" name="website" tabindex="-1" autocomplete="off"></div>
  <button type="submit" class="qly-form-submit" id="qly-form-submit-btn">Book a Free Trial Class</button>
  <div class="qly-form-msg" id="qly-form-msg" role="status" aria-live="polite"></div>
</form>
<script>
(function(){
  var form = document.getElementById('qly-free-trial-form');
  if (!form) return;
  form.addEventListener('submit', function(e){
    e.preventDefault();
    var btn = document.getElementById('qly-form-submit-btn');
    var msg = document.getElementById('qly-form-msg');
    msg.className = 'qly-form-msg';
    msg.textContent = '';
    var data = {
      name: document.getElementById('qly-name').value.trim(),
      email: document.getElementById('qly-email').value.trim(),
      whatsapp: document.getElementById('qly-whatsapp').value.trim(),
      country: document.getElementById('qly-country').value,
      course: document.getElementById('qly-course').value,
      plan: document.getElementById('qly-plan').value,
      timing: document.getElementById('qly-timing').value,
      message: document.getElementById('qly-message').value.trim(),
      website: document.getElementById('qly-website').value
    };
    if (!data.name || !data.email || !data.whatsapp) {
      msg.className = 'qly-form-msg qly-err';
      msg.textContent = 'Please fill in your name, email, and WhatsApp number.';
      return;
    }
    btn.disabled = true;
    btn.textContent = 'Sending...';
    fetch('/wp-json/quranlyhub/v1/free-trial', {
      method: 'POST',
      headers: {'Content-Type': 'application/json'},
      body: JSON.stringify(data)
    }).then(function(r){ return r.json().then(function(j){ return {ok: r.ok, body: j}; }); })
      .then(function(res){
        btn.disabled = false;
        btn.textContent = 'Book a Free Trial Class';
        if (res.ok && res.body.success) {
          msg.className = 'qly-form-msg qly-ok';
          msg.textContent = res.body.message || 'Thank you, we received your request.';
          form.reset();
        } else {
          msg.className = 'qly-form-msg qly-err';
          msg.textContent = (res.body && res.body.message) || 'Something went wrong. Please message us on WhatsApp instead.';
        }
      }).catch(function(){
        btn.disabled = false;
        btn.textContent = 'Book a Free Trial Class';
        msg.className = 'qly-form-msg qly-err';
        msg.textContent = 'Something went wrong. Please message us on WhatsApp instead.';
      });
  });
})();
</script>"},"elements":[]}],"isInner":true}]},{"id":"000001e","elType":"container","settings":{"content_width":"full","flex_direction":"row","flex_wrap":"wrap","background_background":"classic","background_color":"#FFFFFF","padding":{"unit":"px","top":"64","right":"20","bottom":"64","left":"20","isLinked":false},"padding_mobile":{"unit":"px","top":"36","right":"6","bottom":"36","left":"6","isLinked":false},"justify_content":"center"},"elements":[{"id":"000001d","elType":"container","settings":{"content_width":"boxed","flex_direction":"column","max_width":{"unit":"px","size":1100,"sizes":[]},"width":{"unit":"%","size":100,"sizes":[]}},"elements":[{"id":"0000017","elType":"widget","widgetType":"heading","settings":{"title":"Contact: Frequently Asked Questions","header_size":"h2","title_color":"#2B2D42","typography_typography":"custom","typography_font_family":"Playfair Display","typography_font_weight":"700","typography_font_size":{"unit":"px","size":30,"sizes":[]},"typography_font_size_mobile":{"unit":"px","size":24,"sizes":[]},"typography_line_height":{"unit":"em","size":1.2,"sizes":[]},"align":"left","_margin":{"unit":"px","top":"0","right":"0","bottom":"16","left":"0","isLinked":false}},"elements":[],"isInner":true},{"id":"000001c","elType":"widget","widgetType":"accordion","settings":{"tabs":[{"tab_title":"How quickly will you respond?","tab_content":"We aim to respond as quickly as possible, WhatsApp is the fastest way to reach us since we are available 24/7 there.","_id":"0000018"},{"tab_title":"Do I have to use WhatsApp?","tab_content":"No, you can use the form or email instead, though WhatsApp is usually the quickest way to hear back and arrange a trial time.","_id":"0000019"},{"tab_title":"What happens after I submit the form?","tab_content":"Your details are sent directly to our team by email, and we will follow up using the contact information you provide.","_id":"000001a"},{"tab_title":"Is my information kept private?","tab_content":"Your information is o